<script setup lang="ts">
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import MaterialPicker from '../console/MaterialPicker.vue'
import ImageSelectTile from '../console/ImageSelectTile.vue'
import type {OfficialReply} from '~/types/official-account'
const props=defineProps<{disabled?:boolean}>(),model=defineModel<OfficialReply>({required:true}),open=ref(false),busy=ref(false),emit=defineEmits<{busy:[value:boolean]}>()
const tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/shared',type=computed(()=>model.value.type||'text'),cover=computed(()=>type.value==='news'||type.value==='miniprogram'),selectedId=computed(()=>cover.value?model.value.coverMaterialId:model.value.materialId)
const items=[{key:'text',label:'文本',icon:'i-lucide-file-text'},{key:'image',label:'图片',icon:'i-lucide-images'},{key:'video',label:'视频',icon:'i-lucide-video'},{key:'news',label:'图文',icon:'i-lucide-layout-grid'},{key:'miniprogram',label:'小程序卡片',icon:'i-lucide-smartphone'}] as const
function pending(value:boolean){busy.value=value;emit('busy',value)}
function select(id:string|null){if(cover.value)model.value.coverMaterialId=id;else model.value.materialId=id}
</script>
<template><div class="official-reply-editor overflow-hidden rounded-md border border-default"><div class="flex flex-wrap gap-1 border-b border-default p-2"><UButton v-for="item in items" :key="item.key" type="button" :icon="item.icon" :color="type===item.key?'primary':'neutral'" :variant="type===item.key?'soft':'ghost'" :disabled="disabled||busy" @click="model.type=item.key">{{item.label}}</UButton></div>
 <div class="reply-editor-body" :class="type==='text'?'reply-editor-body-text':'space-y-5 p-4 sm:p-6'"><template v-if="type==='text'"><UTextarea v-model="model.text" :rows="8" :maxlength="600" class="official-reply-text w-full" :ui="{base:'ring-0 shadow-none focus:ring-0 rounded-none bg-transparent'}" :disabled="disabled" aria-label="回复文本" placeholder="请输入回复内容"/><p class="px-4 pb-3 text-right text-xs text-muted">{{model.text.length}} / 600</p></template>
 <template v-else><template v-if="cover"><ConsoleSettingsField :label="type==='news'?'图文标题':'卡片标题'"><ConsoleInput v-model="model.title" class="w-full" :maxlength="60" :disabled="disabled" aria-label="回复标题"/></ConsoleSettingsField><ConsoleSettingsField v-if="type==='news'" label="图文描述"><UTextarea v-model="model.description" class="w-full" :rows="3" :maxlength="300" :disabled="disabled" aria-label="图文描述"/></ConsoleSettingsField><ConsoleSettingsField v-if="type==='news'" label="跳转链接"><ConsoleInput v-model="model.url" type="url" class="w-full" :disabled="disabled" aria-label="图文跳转链接" placeholder="https://"/></ConsoleSettingsField><template v-if="type==='miniprogram'"><ConsoleSettingsField label="小程序 AppID"><ConsoleInput v-model="model.appId" pattern="wx[a-fA-F0-9]{16}" class="w-full" :disabled="disabled" aria-label="卡片小程序 AppID"/><p class="mt-2 text-xs text-muted">小程序需已与本公众号关联。</p></ConsoleSettingsField><ConsoleSettingsField label="页面路径"><ConsoleInput v-model="model.pagePath" class="w-full" :disabled="disabled" aria-label="卡片页面路径" placeholder="pages/index/index"/></ConsoleSettingsField></template></template>
 <ConsoleSettingsField v-if="type!=='video'" :label="cover?'封面图片':'回复图片'"><ImageSelectTile :src="selectedId?'/api/v1'+endpoint+'/'+selectedId+'/content':null" :label="cover?'回复封面':'回复图片'" :disabled="disabled||busy" :removable="!!selectedId" @select="open=true" @remove="select(null)"/><p class="mt-2 text-xs text-muted">从本站素材库选择或上传，移除只解除关联。</p></ConsoleSettingsField>
 <template v-else><div v-if="selectedId" class="space-y-3"><video :src="'/api/v1'+endpoint+'/'+selectedId+'/content'" controls preload="metadata" class="max-h-72 max-w-full rounded-md"/><div class="flex gap-2"><UButton type="button" color="neutral" variant="outline" :disabled="disabled||busy" @click="open=true">更换视频</UButton><UButton type="button" color="neutral" variant="outline" icon="i-lucide-x" :disabled="disabled||busy" @click="select(null)">移除视频</UButton></div></div><UButton v-else type="button" class="flex min-h-52 w-full flex-col justify-center gap-3 border-dashed" color="neutral" variant="outline" icon="i-lucide-plus" :disabled="disabled||busy" @click="open=true">从素材库选择或上传视频</UButton><ConsoleSettingsField label="视频标题"><ConsoleInput v-model="model.title" class="w-full" :maxlength="60" :disabled="disabled"/></ConsoleSettingsField><ConsoleSettingsField label="视频说明"><UTextarea v-model="model.description" class="w-full" :rows="3" :maxlength="300" :disabled="disabled"/></ConsoleSettingsField></template></template>
 </div><MaterialPicker v-model:open="open" portal="tenant" :endpoint="endpoint" :kind="type==='video'?'video':'image'" @busy="pending" @select="select($event.id)"/></div></template>

<style scoped>.official-reply-editor{display:flex;flex-direction:column;min-width:0}.official-reply-editor:focus-within{border-color:var(--ui-primary)}.reply-editor-body-text{display:flex;flex:1;flex-direction:column}.official-reply-text{display:flex;flex-direction:column;align-items:stretch;flex:1;min-height:14rem}.official-reply-text :deep(textarea){flex:1;min-height:14rem;resize:none;padding:1rem}@media(max-width:639px){.official-reply-text,.official-reply-text :deep(textarea){min-height:12rem}}</style>
